import {Banner} from '@primer/react'

export function CustomModelsEnabledPolicyBanner({
  customModelsEnabled,
  enterpriseSlug,
  showAiControls,
  totalModels,
}: {
  customModelsEnabled: boolean
  enterpriseSlug: string
  showAiControls?: boolean
  totalModels: number
}) {
  if (customModelsEnabled || totalModels < 1) return null
  const settingsUrl = showAiControls
    ? `/enterprises/${enterpriseSlug}/ai-controls/copilot`
    : `/enterprises/${enterpriseSlug}/settings/copilot`
  return (
    <Banner
      title="Custom models are disabled for this enterprise"
      hideTitle
      variant="warning"
      className="tmp-mb-3"
      primaryAction={
        <Banner.PrimaryAction as="a" href={settingsUrl}>
          View policy settings
        </Banner.PrimaryAction>
      }
    >
      <p className="mb-0">
        No custom models can be used while the &ldquo;Enable custom models&rdquo; policy is disabled.
      </p>
    </Banner>
  )
}
