import {clsx} from 'clsx'
import {useMutation} from '@github-ui/react-query'
import {Button, Stack, UnderlineNav} from '@primer/react'
import {Dialog, type DialogProps} from '@primer/react/experimental'
import {type FormEvent, startTransition, useCallback, useId, useRef, useState} from 'react'
import {ModelConfigurationFields} from '@github-ui/copilot-byok-settings/components/ModelConfigurationFields'
import {getErrorMessageFromResponse} from '@github-ui/copilot-byok-settings/helpers/extract-errors'
import {
  getGeneralValidationKind,
  type ValidationKind,
  validationKindFromZodError,
} from '@github-ui/copilot-byok-settings/helpers/validation'
import type {CustomModel} from '@github-ui/copilot-byok-settings/types'

import {updateCustomModelMutationOptions, updateCustomModelSchema} from '../queries/update-custom-model'
import type {EnterpriseCustomModelAccessStatus} from '../types'
import {ModelOrgAccessControls} from './ModelOrgAccessControls'

type DialogTab = 'general' | 'access'

interface ModelConfigurationDialogProps {
  customKeyName: string
  enterpriseSlug: string
  model: CustomModel
  modelAccessStatus?: EnterpriseCustomModelAccessStatus
  onUpdateModel: () => void
}

export function ModelConfigurationDialog({
  customKeyName,
  enterpriseSlug,
  model,
  modelAccessStatus,
  onUpdateModel,
}: ModelConfigurationDialogProps) {
  const [open, setOpen] = useState(false)
  const [activeTab, setActiveTab] = useState<DialogTab>('general')
  const showTabs = model.enabled
  const baseId = useId()
  const formId = `model-config-form-${baseId}`
  const dialogToggleButtonRef = useRef<HTMLButtonElement>(null)
  const onClose = useCallback(() => setOpen(false), [])
  const [validation, setValidation] = useState<Record<string, ValidationKind>>()
  const {mutate, isPending} = useMutation(updateCustomModelMutationOptions(enterpriseSlug))
  const onSuccessfulUpdate = useCallback(() => {
    onUpdateModel()
    onClose()
  }, [onClose, onUpdateModel])
  const onSubmit = useCallback(
    (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      if (isPending) return

      const formData = new FormData(event.currentTarget)
      const payload = Object.assign(
        {id: model.id, enabled: model.enabled},
        Object.fromEntries(formData.entries()),
      ) as Record<string, unknown>

      const {success, data: validatedUpdate, error: zodError} = updateCustomModelSchema.safeParse(payload)
      if (!success) {
        setValidation(validationKindFromZodError(zodError))
        return
      }

      startTransition(() => {
        setValidation(undefined)
        mutate(validatedUpdate, {
          onSuccess: onSuccessfulUpdate,
          async onError(mutationError) {
            const message = await getErrorMessageFromResponse(mutationError)
            setValidation(getGeneralValidationKind(message, mutationError.message))
          },
        })
      })
    },
    [isPending, model, mutate, onSuccessfulUpdate],
  )

  return (
    <>
      <Button
        aria-label={`Configure ${model.name ?? model.slug} from ${customKeyName}`}
        variant="invisible"
        ref={dialogToggleButtonRef}
        onClick={() => setOpen(!open)}
      >
        {getDialogToggleButtonText(modelAccessStatus)}
      </Button>
      {open && (
        <Dialog
          onClose={onClose}
          title={`Edit configuration for ${model.slug} (${customKeyName})`}
          returnFocusRef={dialogToggleButtonRef}
          renderBody={DialogBodyWithoutPadding}
          width="large"
          height="auto"
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Cancel',
              onClick: onClose,
              disabled: isPending,
            },
            {
              buttonType: 'primary',
              content: 'Save',
              disabled: isPending,
              loading: isPending,
              type: 'submit',
              form: formId,
              loadingAnnouncement: 'Saving model configuration',
            },
          ]}
        >
          <Stack as="form" id={formId} className="height-full" onSubmit={onSubmit}>
            {showTabs && <DialogTabs activeTab={activeTab} onSelect={tab => setActiveTab(tab)} />}
            <ModelConfigurationFields
              className={clsx('tmp-px-3', {'tmp-pt-3': !showTabs, 'd-none': activeTab !== 'general' && showTabs})}
              disabled={isPending}
              model={model}
              validation={validation}
            />
            {showTabs && (
              <ModelOrgAccessControls
                modelAccessStatus={modelAccessStatus}
                modelId={model.id}
                enterpriseSlug={enterpriseSlug}
                className={clsx({'d-none': activeTab !== 'access'})}
              />
            )}
          </Stack>
        </Dialog>
      )}
    </>
  )
}

function DialogBodyWithoutPadding({children}: React.PropsWithChildren<DialogProps>) {
  return <Dialog.Body className="p-0">{children}</Dialog.Body>
}

function DialogTabs({activeTab, onSelect}: {activeTab: DialogTab; onSelect: (tab: DialogTab) => void}) {
  return (
    <UnderlineNav aria-label="Model configuration sections">
      <UnderlineNav.Item
        as="button"
        type="button"
        onSelect={() => onSelect('general')}
        aria-current={activeTab === 'general' ? 'location' : undefined}
      >
        General
      </UnderlineNav.Item>
      <UnderlineNav.Item
        as="button"
        type="button"
        onSelect={() => onSelect('access')}
        aria-current={activeTab === 'access' ? 'location' : undefined}
      >
        Access
      </UnderlineNav.Item>
    </UnderlineNav>
  )
}

const defaultDialogToggleButtonText = 'Configure'
function getDialogToggleButtonText(modelAccessStatus?: EnterpriseCustomModelAccessStatus) {
  if (!modelAccessStatus) return defaultDialogToggleButtonText
  if (modelAccessStatus.enabledForAllOrgs) return 'All organizations'
  if (modelAccessStatus.allowedOrgIds) {
    const totalOrgs = modelAccessStatus.allowedOrgIds.length
    if (totalOrgs < 1) return defaultDialogToggleButtonText
    const units = totalOrgs === 1 ? 'organization' : 'organizations'
    return `${totalOrgs} ${units}`
  }
  return defaultDialogToggleButtonText
}
