import {type ComponentType, createElement} from 'react'

import {
  awsBedrockFormSchema,
  awsBedrockFormSchemaPreprocessor,
} from '@github-ui/copilot-byok-settings/components/providers/awsbedrock/AwsBedrockFields'

import {AzureAIFields, azureFormSchema} from './azureai/AzureAIFields'
import {GenericProviderFields, genericProviderFormSchema} from './GenericProvider'
import type {ProviderFieldProps} from './types'
import type {Provider, ProviderSchemaPreprocessorMapping} from '@github-ui/copilot-byok/providers'
import {AwsBedrockFields} from './awsbedrock/AwsBedrockFields'
import {
  OpenAICompatibleFields,
  openAICompatibleFormSchema,
  openAICompatibleFormSchemaPreprocessor,
} from './openaicompatible/OpenAICompatibleFields'

// Note: GenericProviderFields must be last to ensure it is the fallback option
export const providerSchema = [
  azureFormSchema,
  awsBedrockFormSchema,
  openAICompatibleFormSchema,
  genericProviderFormSchema,
] as const

const providerSchemaPreprocessors = {
  azureai: undefined,
  awsbedrock: awsBedrockFormSchemaPreprocessor,
  openai: undefined,
  anthropic: undefined,
  xai: undefined,
  googleaistudio: undefined,
  openaicompatible: openAICompatibleFormSchemaPreprocessor,
} as const satisfies ProviderSchemaPreprocessorMapping

export function preprocessProviderFormPayload(provider: Provider, payload: Record<string, unknown>) {
  const preprocessor = providerSchemaPreprocessors[provider]
  return preprocessor ? preprocessor(payload) : payload
}

export const providerFields = {
  azureai: AzureAIFields,
  awsbedrock: AwsBedrockFields,
  // eslint-disable-next-line @github-ui/github-monorepo/no-react-create-element -- Convert to JSX. This may require using a tsx file.
  openai: props => createElement(GenericProviderFields, {provider: 'openai', ...props}),
  openaicompatible: OpenAICompatibleFields,
  // eslint-disable-next-line @github-ui/github-monorepo/no-react-create-element -- Convert to JSX. This may require using a tsx file.
  anthropic: props => createElement(GenericProviderFields, {provider: 'anthropic', ...props}),
  // eslint-disable-next-line @github-ui/github-monorepo/no-react-create-element -- Convert to JSX. This may require using a tsx file.
  xai: props => createElement(GenericProviderFields, {provider: 'xai', ...props}),
  // eslint-disable-next-line @github-ui/github-monorepo/no-react-create-element -- Convert to JSX. This may require using a tsx file.
  googleaistudio: props => createElement(GenericProviderFields, {provider: 'googleaistudio', ...props}),
} as const satisfies {
  [k in Provider]: ComponentType<ProviderFieldProps<k>>
}
