import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useQuery} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {getMaybeJSONErrorMessage} from '@github-ui/copilot-byok-settings/helpers/extract-errors'
import type {Provider} from '@github-ui/copilot-byok/providers'
import type {ProviderDataFor, SelectorCustomModel} from '@github-ui/copilot-byok-settings/types'

export function useFetchProviderModels<P extends Provider = Provider>({
  apiKey,
  provider,
  customKeyId,
  providerData,
  enabled,
  enterpriseSlug,
}: {
  apiKey?: string
  provider: P
  customKeyId?: number
  providerData?: ProviderDataFor<P>
  enabled: boolean
  enterpriseSlug: string
}) {
  const additionalFields = {
    custom_key_id: customKeyId,
    access_key: providerData && 'accessKey' in providerData ? providerData.accessKey : undefined,
    base_url: providerData && 'baseUrl' in providerData ? providerData.baseUrl : undefined,
    region: providerData && 'region' in providerData ? providerData.region : undefined,
  }
  const queryKey = ['byok-settings', 'availableModels', enterpriseSlug, provider, apiKey, additionalFields]

  const query = useQuery({
    queryKey,
    initialData: [],
    gcTime: 1 * 60 * 1000, // 1 minute
    enabled,
    async queryFn({signal}) {
      const r = await reactFetchJSON(
        // Businesses::CopilotByokProviderModelsSettingsController#create endpoint in github/github
        `/enterprises/${enterpriseSlug}/settings/copilot/custom-models/${provider as string}/models`,
        {
          method: 'POST',
          signal,
          body: {
            api_key: apiKey,
            ...additionalFields,
          },
        },
      )

      if (!r.ok) {
        const errorMessage = await getMaybeJSONErrorMessage(r)
        throw new ResponseError(errorMessage ?? 'Failed to fetch available models', r)
      }

      return (await r.json()) as SelectorCustomModel[]
    },
  })

  return {...query, queryKey}
}
