import {Banner, Button} from '@primer/react'
import {useCallback, useRef, useState} from 'react'

import {setBanner} from '@github-ui/page-banner'
import type {CreateCustomKeyMutationData} from '@github-ui/copilot-byok-settings/types'
import {AddApiKeyDialog} from './AddApiKeyDialog'

export function AddApiKeyButton({
  onSuccess,
  publicKey,
  enterpriseSlug,
}: {
  onSuccess?: (data: CreateCustomKeyMutationData) => void
  publicKey: string
  enterpriseSlug: string
}) {
  const ref = useRef<HTMLButtonElement>(null)

  const [show, setShow] = useState(false)

  const onSuccessHandler = useCallback(
    (data: CreateCustomKeyMutationData) => {
      setShow(false)
      setBanner(
        <Banner
          role="banner"
          title="Success"
          variant="success"
          hideTitle
          description={
            <>
              API key &quot;<strong>{data.name}</strong>&quot; successfully added.
            </>
          }
        />,
      )
      onSuccess?.(data)
    },
    [onSuccess],
  )

  return (
    <>
      <Button ref={ref} variant="primary" onClick={() => setShow(true)}>
        Add API key
      </Button>

      {show && (
        <AddApiKeyDialog
          anchorRef={ref}
          onCancel={() => setShow(false)}
          onSuccess={onSuccessHandler}
          publicKey={publicKey}
          enterpriseSlug={enterpriseSlug}
        />
      )}
    </>
  )
}
